export const QUESTIONS_BY_ID: Record<string, Question> = Object.fromEntries(QUESTIONS.map((q) => [q.id, q]));

/** A pack's questions, in spreadsheet order. */
export function getQuestionsForPack(packId: string): Question[] {
  return (PACKS_BY_ID[packId]?.questionIds ?? []).map((id) => QUESTIONS_BY_ID[id]);
}
